package com.example.puller.config;import org.apache.kafka.clients.admin.NewTopic;import org.apache.kafka.clients.producer.ProducerConfig;import org.apache.kafka.common.serialization.StringSerializer;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.kafka.core.*;import java.util.*;@Configuration public class KafkaConfig{@Bean NewTopic topic(@Value("${order.poller.topic.name}")String n){return new NewTopic(n,3,(short)1);}@Bean ProducerFactory<String,String> producerFactory(@Value("${spring.kafka.bootstrap-servers}")String b){Map<String,Object> p=new HashMap<String,Object>();p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,b);p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,StringSerializer.class);p.put(ProducerConfig.ACKS_CONFIG,"all");p.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG,true);return new DefaultKafkaProducerFactory<String,String>(p);}@Bean KafkaTemplate<String,String> kafkaTemplate(ProducerFactory<String,String> pf){return new KafkaTemplate<String,String>(pf);}}
